function tget(u,ms){var c=window.AbortController?new AbortController():null,t=setTimeout(function(){if(c)c.abort()},ms||8000);return fetch(u,{cache:'no-store',credentials:'omit',signal:c?c.signal:undefined}).then(function(r){clearTimeout(t);return r},function(e){clearTimeout(t);throw e})}
function healthDraw(){var b=$('#admk-hl');if(!b)return;b.innerHTML='<p class="ak-n">בודק…</p>';
  Promise.all(SITES.map(function(s){var t0=Date.now();return tget(s[2]+'/__ping?t='+t0).then(function(r){var ms=Date.now()-t0;if(r.ok)return r.json().then(function(j){return{s:s,up:1,ms:ms,j:j}});return tget(s[2]+'/cfg.json?t='+t0).then(function(r2){return{s:s,up:r2.ok?1:0,ms:Date.now()-t0,j:null}})}).catch(function(){return{s:s,up:0}})})).then(function(R){
   b.innerHTML=R.map(function(x){var j=x.j||{},f=[];if(j.maint)f.push('<span class="ak-bad">🛠️ תחזוקה פעילה</span>');if(j.msg)f.push('📣 הודעה פעילה');if(j.wn)f.push('✨ מה חדש');if(j.off)f.push('🎛️ '+j.off+' כבויים');
    return'<div class="ak-fb"><div class="ak-row" style="justify-content:space-between"><b>'+(x.up?'✅':'❌')+' '+E(x.s[1])+(x.s[0]===K.app?' <small class="ak-n">(כאן)</small>':'')+'</b>'+(x.s[0]!==K.app?'<a href="'+x.s[2]+'/admin/" target="_blank" rel="noopener">לניהול ←</a>':'')+'</div><small>'+(x.up?'עולה · '+x.ms+' מ״ש'+(j.v||j.b?' · גרסה '+E(j.v||'')+(j.b?' ('+E(j.b)+')':''):''):'<span class="ak-bad">לא עונה</span>')+'</small>'+(f.length?'<small>'+f.join(' · ')+'</small>':'')+'</div>'}).join('')+'<p class="ak-n">נבדק '+fmt(Date.now())+'</p>'})}
/* ---------- translation check (and fixes for apps that support them) ---------- */
var TRR=null,TRL='',TRQ='',TRV={};
function trRun(){var b=$('#admk-tr');if(!b||!K.i18n)return;b.innerHTML='<p class="ak-n">בודק… (כמה שניות)</p>';var I=K.i18n,pr;
  if(I.fn&&typeof window[I.fn]==='function')pr=Promise.resolve(window[I.fn](CFG.tr||{}));
  else if(I.files)pr=Promise.all(I.files.map(function(l){return fetch(I.path+l+'.json?t='+Date.now(),{cache:'no-store'}).then(function(r){return r.ok?r.json():{}}).catch(function(){return{}})})).then(function(A){var T=A.map(function(j){return j&&j.t&&typeof j.t==='object'?j.t:(j||{})}),all={};T.forEach(function(j){Object.keys(j).forEach(function(k){all[k]=1})});var keys=Object.keys(all),o={};I.files.forEach(function(l,i){var miss=keys.filter(function(k){return!(k in T[i])}),tot=Math.max(keys.length,+A[i].n||0);o[l]={total:tot,missing:miss,extra:Math.max(0,tot-keys.length)}});return o});
  else pr=Promise.resolve({});
  pr.then(function(o){TRR=o||{};trDraw()}).catch(function(){b.innerHTML='<p class="ak-bad ak-n">הבדיקה לא הצליחה</p>'})}
function trDraw(){var b=$('#admk-tr');if(!b||!TRR)return;[].slice.call(document.querySelectorAll('#admk .tr_in')).forEach(function(x){TRV[x.getAttribute('data-s')]=x.value});var I=K.i18n,ov=CFG.tr||{};
  var h='<ul>'+Object.keys(TRR).map(function(l){var x=TRR[l],n=x.missing.length+(x.extra||0);return'<li><b>'+E(LN[l]||l)+':</b> '+(n?'<span class="ak-bad">'+n+' חסרים</span>':'<span class="ak-ok">הכול מתורגם ✓</span>')+' מתוך '+x.total+(Object.keys(ov[l]||{}).length?' · '+Object.keys(ov[l]).length+' תוקנו מכאן':'')+(n||Object.keys(ov[l]||{}).length?' <a href="#" data-a="trl" data-l="'+E(l)+'">'+(I.fix?'הצגה ותיקון':'הצגה')+'</a>':'')+'</li>'}).join('')+'</ul>';
  if(TRL&&TRR[TRL]){var miss=TRR[TRL].missing.filter(function(s){return!TRQ||s.toLowerCase().indexOf(TRQ.toLowerCase())>=0}),dir=TRL==='ar'||TRL==='he'?'rtl':'ltr';
   h+='<h3 style="margin:6px 0 0;font-size:15px">'+E(LN[TRL]||TRL)+'</h3><input type="text" id="tr_q" placeholder="חיפוש…" value="'+E(TRQ)+'" dir="auto">';
   if(I.fix){h+='<p class="ak-n">כתבו את התרגום מתחת לטקסט. התיקונים נכנסים לאפליקציה אצל כולם תוך דקה, בלי עדכון גרסה.</p>'+miss.slice(0,40).map(function(s,i){return'<div class="ak-fb"><small dir="ltr" style="text-align:left">'+E(s)+'</small><input type="text" class="tr_in" data-s="'+E(s)+'" dir="'+dir+'" maxlength="600" value="'+E(TRV[s]||'')+'"></div>'}).join('')+(miss.length>40?'<p class="ak-n">מוצגים 40 מתוך '+miss.length+'. אחרי השמירה יופיעו הבאים.</p>':'')+'<div class="ak-row"><button class="ak-b" data-a="trsave">שמירת התרגומים</button></div>';
    var o=ov[TRL]||{},ks=Object.keys(o);if(ks.length)h+='<details><summary class="ak-n">תיקונים שנשמרו ('+ks.length+')</summary>'+ks.map(function(k){return'<div class="ak-fb"><small dir="ltr" style="text-align:left">'+E(k)+'</small><p dir="'+dir+'">'+E(o[k])+'</p><div class="ak-row"><button class="ak-b ak-g" data-a="trdel" data-s="'+E(k)+'">מחיקת התיקון</button></div></div>'}).join('')+'</details>'}
   else h+='<p class="ak-n">מזהי הטקסטים שחסרים (התרגום עצמו מתעדכן בבנייה של האפליקציה):</p><ul dir="ltr" style="text-align:left">'+miss.slice(0,150).map(function(s){return'<li><small>'+E(s)+'</small></li>'}).join('')+'</ul>'+(miss.length>150?'<p class="ak-n">ועוד '+(miss.length-150)+'</p>':'')}
  b.innerHTML=h;var q=$('#tr_q');if(q)q.oninput=function(){TRQ=q.value;var pos=q.selectionStart;trDraw();var q2=$('#tr_q');if(q2){q2.focus();try{q2.setSelectionRange(pos,pos)}catch(e){}}}}
function trSave(){var o=JSON.parse(JSON.stringify(CFG.tr||{})),n=0;o[TRL]=o[TRL]||{};[].slice.call(document.querySelectorAll('#admk .tr_in')).forEach(function(x){TRV[x.getAttribute('data-s')]=x.value});var miss=(TRR[TRL]||{missing:[]}).missing;Object.keys(TRV).forEach(function(k){var v=String(TRV[k]||'').trim();if(v&&miss.indexOf(k)>=0){o[TRL][k]=v.slice(0,600);n++}});TRV={};
  if(!n){toast('לא נכתב שום תרגום');return}return save({tr:o},{t:n+' תיקוני תרגום ל'+(LN[TRL]||TRL)},n+' תרגומים נשמרו ✓').then(function(){if(TRR&&TRR[TRL])TRR[TRL].missing=TRR[TRL].missing.filter(function(s){return!(s in o[TRL])});trDraw()})}
/* ---------- view the regular site as a user ---------- */
var PVSNAP=null;
function pvSnap(){if(PVSNAP)return;PVSNAP={};(K.langLS||[]).forEach(function(k){PVSNAP[k]=ls(k)})}
function pvRestore(){if(!PVSNAP)return;Object.keys(PVSNAP).forEach(function(k){try{if(PVSNAP[k]==null)localStorage.removeItem(k);else localStorage.setItem(k,PVSNAP[k])}catch(e){}});PVSNAP=null}
function pvOpen(l){var b=$('#admk-pv');if(!b)return;pvSnap();var u='/'+(l?'?lang='+encodeURIComponent(l):'');
  b.innerHTML='<div class="ak-row" style="justify-content:space-between"><span class="ak-n">'+(l?E(LN[l]||l):'כמו שמשתמש רגיל רואה')+' · מסך טלפון</span><button class="ak-b ak-g" data-a="pv0">סגירת התצוגה</button></div><iframe class="ak-frame" title="האתר הרגיל" src="'+u+'"></iframe>';
  var f=b.querySelector('iframe');f.onload=function(){setTimeout(pvRestore,1500)}}
