/* ---------- backup, restore from file, copy between apps ---------- */
var PICK=['msg','wn','off','maint','cstart','tr'];
function bkObj(){return{kind:'admin-settings',app:K.app,at:Date.now(),cfg:CFG,tpl:ST.tpl||[]}}
function copyTxt(t,ok){var done=function(){toast(ok||'הועתק ✓')};try{navigator.clipboard.writeText(t).then(done,function(){fb()})}catch(e){fb()}function fb(){var x=$('#bk_in');if(x){x.value=t;x.select();toast('סמנו והעתיקו מהתיבה')}}}
function bkFile(){var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(bkObj(),null,1)],{type:'application/json'}));a.download=(K.app||'app')+'-admin-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();setTimeout(function(){a.remove()},500)}
function bkImport(txt){var o;try{o=JSON.parse(txt)}catch(e){toast('זה לא גיבוי תקין');return}var src=o&&o.cfg?o.cfg:o;if(!src||typeof src!=='object'){toast('זה לא גיבוי תקין');return}
  var other=o.app&&o.app!==K.app,keys=PICK.filter(function(k){return k in src&&(!other||['msg','wn','maint'].indexOf(k)>=0)});if(!keys.length&&!(o.tpl&&o.tpl.length)){toast('לא נמצאו הגדרות לטעינה');return}
  var patch={};keys.forEach(function(k){patch[k]=JSON.parse(JSON.stringify(src[k]))});if(patch.msg&&patch.msg.on)patch.msg.id=String(Date.now());if(patch.wn&&patch.wn.on)patch.wn.id=String(Date.now()+1);
  var names={msg:'הודעה',wn:'מה חדש',off:'חלקים כבויים',maint:'תחזוקה',cstart:'מאיפה להתחיל',tr:'תיקוני תרגום'};
  if(!confirm('לטעון: '+keys.map(function(k){return names[k]}).join(', ')+(o.tpl&&o.tpl.length&&!other?', תבניות תשובה':'')+'?\nהמצב הנוכחי יישמר בהיסטוריה.'))return;
  var p=Promise.resolve();if(o.tpl&&o.tpl.length&&!other){ST.tpl=o.tpl.slice(0,20);p=api('/admin/__state',{state:{tpl:ST.tpl}}).catch(function(){})}
  return p.then(function(){return keys.length?save(patch,{t:'נטענו הגדרות'+(other?' מאפליקציה אחרת':' מגיבוי')+': '+keys.map(function(k){return names[k]}).join(', ')},'ההגדרות נטענו ✓'):(toast('התבניות נטענו ✓'),draw())})}
/* ---------- what's scheduled ---------- */
function calItems(){var now=Date.now(),L=[],m=CFG.msg||{},w=CFG.wn||{},mt=CFG.maint||{};
  if(m.on&&m.from>now)L.push([m.from,'📣 ההודעה תתחיל להופיע','msg.from']);if(m.on&&m.to>now)L.push([m.to,'📣 ההודעה תוסר','msg.to']);
  if(w.on&&w.from>now)L.push([w.from,'✨ "מה חדש" יופיע','wn.from']);if(mt.on&&mt.from>now)L.push([mt.from,'🛠️ מצב תחזוקה יתחיל','maint.from']);if(mt.on&&mt.to>now)L.push([mt.to,'🛠️ מצב תחזוקה יסתיים','maint.to']);
  return L.sort(function(a,b){return a[0]-b[0]})}
function calCancel(k){var p=k.split('.'),o=Object.assign({},CFG[p[0]]||{}),patch={},t;if(p[1]==='from'){o.on=false;t='בוטל תזמון: '+({msg:'הודעה',wn:'מה חדש',maint:'תחזוקה'})[p[0]]}else{delete o.to;t='בוטל זמן סיום: '+({msg:'הודעה',maint:'תחזוקה'})[p[0]]}patch[p[0]]=o;return save(patch,{t:t},'התזמון בוטל')}
/* ---------- link and QR code to share ---------- */
var QRP=null;
function qrLib(){if(window.QRX)return Promise.resolve();if(QRP)return QRP;QRP=new Promise(function(ok,no){var s=document.createElement('script');s.src='/admin/__qr.js';s.onload=ok;s.onerror=function(){QRP=null;no()};document.head.appendChild(s)});return QRP}
function lkUrl(){var pth=($('#lk_p')||{}).value||'/',l=($('#lk_l')||{}).value||'';var u=new URL(pth,location.origin);if(l)u.searchParams.set('lang',l);return u.href}
