function qrDraw(){var box=$('#admk-qr');if(!box)return;qrLib().then(function(){var q=window.QRX.make(lkUrl()),n=q.getModuleCount(),pad=4,sc=Math.max(4,Math.floor(264/(n+pad*2))),sz=(n+pad*2)*sc,c=document.createElement('canvas');c.width=c.height=sz;var g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,sz,sz);g.fillStyle='#000';
  for(var r=0;r<n;r++)for(var k=0;k<n;k++)if(q.isDark(r,k))g.fillRect((k+pad)*sc,(r+pad)*sc,sc,sc);c.style.cssText='width:220px;height:220px;border-radius:12px;image-rendering:pixelated';box.innerHTML='';box.appendChild(c);
  var a=el('<div class="ak-row"><button class="ak-b ak-g" data-a="qrsave">שמירת התמונה</button></div>');box.appendChild(a)}).catch(function(){box.innerHTML='<p class="ak-bad ak-n">לא הצלחתי ליצור קוד QR</p>'})}
